import { useState } from 'react';

export type Props = { onRecord: (value: number) => void };

export function Component({ onRecord }: Props) {
  const [reading, setReading] = useState('');
  const [history, setHistory] = useState<number[]>([]);
  const [hasError, setHasError] = useState(false);

  return (
    <div
      data-testid="panel"
      style={{
        display: 'grid',
        background: '#eef4ff',
        color: '#17345c',
        padding: 12,
        gap: 6,
      }}
    >
      <label>
        Reading
        <input
          type="text"
          value={reading}
          onChange={(event) => setReading(event.target.value)}
        />
      </label>
      <button
        type="button"
        onClick={() => {
          const text = reading.trim();
          const value = Number(text);
          if (!/^-?\d+$/.test(text) || !Number.isSafeInteger(value)) {
            setHasError(true);
            return;
          }
          setHistory((previous) => [...previous, value]);
          setReading('');
          setHasError(false);
          onRecord(value);
        }}
      >
        Record
      </button>
      <button
        type="button"
        onClick={() => {
          setHistory([]);
          setReading('');
          setHasError(false);
        }}
      >
        Clear
      </button>
      {hasError && <div role="alert">Invalid reading</div>}
      <output aria-label="Latest">
        {history.length === 0 ? 'None' : String(history[history.length - 1])}
      </output>
      <ul aria-label="History">
        {history.map((value, index) => (
          <li key={index}>{String(value)}</li>
        ))}
      </ul>
    </div>
  );
}
```

작은 기능의 상태와 스타일을 한 파일에 두고, 공개 props와 빈 숫자 배열에 필요한 타입만 명시했습니다. 입력 검증과 콜백은 Record 동작에서 처리하며 기본 입력·버튼 요소와 접근성 이름으로 키보드 사용과 결과 확인을 지원합니다.
